import React from 'react';

import { HikingContext } from '@apps/Hiking/@contexts/hikingContext';
import { getHikingJointlyEquipmentNameByType } from '@apps/Hiking/@helpers/jointlyEquipment.helper';
import { HikingJointlyEquipmentType } from '@apps/Hiking/@types/DTO/hikingJointlyEquipment.dto.types';
import { IHikingJointlyEquipment } from '@apps/Hiking/@types/hikingJointlyEquipment.types';
import A4Page from '@components/A4Page';
import { digitsDivision } from '@helpers/formatHelper';

interface IHikingPrintJointlyEquipmentProps {
  jointlyEquipment: IHikingJointlyEquipment[];
  type: HikingJointlyEquipmentType;
}

const HikingPrintJointlyEquipment = ({
  jointlyEquipment,
  type,
}: IHikingPrintJointlyEquipmentProps) => {
  const hikingData = React.useContext(HikingContext);
  if (!hikingData) return 'has no hiking data';

  return (
    <A4Page>
      <h2>{getHikingJointlyEquipmentNameByType(type)}</h2>
      <table className="table table-sm table-condensed table-bordered">
        <thead>
          <tr>
            <th>
              <small>{getHikingJointlyEquipmentNameByType(type, 1)}</small>
            </th>
            <th>
              <small>Комментарий</small>
            </th>
            <th>
              <small>Вес</small>
            </th>
            <th>
              <small>Участники</small>
            </th>
          </tr>
        </thead>
        <tbody>
          {jointlyEquipment.map((item) => {
            return (
              <tr key={item.id}>
                <td>
                  <small>{item.name}</small>
                </td>
                <td className="text-end">
                  <em>
                    <small>{item.comment}</small>
                  </em>
                </td>
                <td className="text-end">
                  <small>{item.equip?.weight}</small>
                </td>
                <td>
                  <ol className="my-0">
                    {item.members.map((m) => {
                      return (
                        <li key={m.id}>
                          <small>
                            {m.user.surname} {m.user.name}
                          </small>
                          {m.comment.length > 0 && (
                            <>
                              <br />
                              <small>
                                <em className="text-info">{m.comment}</em>
                              </small>
                            </>
                          )}
                        </li>
                      );
                    })}
                  </ol>
                </td>
              </tr>
            );
          })}
        </tbody>
        <tfoot>
          <tr>
            <th className="text-end">
              <small>
                Итого {getHikingJointlyEquipmentNameByType(type, 5).toLocaleLowerCase()}:
              </small>
            </th>
            <th className="text-end">
              <small className="text-danger">{jointlyEquipment.length}&thinsp;шт.</small>
            </th>
            <th className="text-end">
              <small>
                {digitsDivision(jointlyEquipment.reduce((a, v) => a + v.equip!.weight, 0))}
              </small>
            </th>
            <th></th>
          </tr>
        </tfoot>
      </table>
    </A4Page>
  );
};

export default HikingPrintJointlyEquipment;
