import React from 'react';

import clsx from 'clsx';

import { IDayData } from '@apps/Hiking/@helpers/hikingDays.helper';
import { IHikingData } from '@apps/Hiking/@types/hiking.types';
import { IHikingMenuExtendedProduct, IHikingMenuFood } from '@apps/Hiking/@types/hikingMenu.types';
import RecipeCookingInfo from '@apps/Recipes/components/RecipeCookingInfo';
import { A4SubPage } from '@components/A4Page';
import { formattedLocaleTime } from '@helpers/dateHelper';
import { round } from '@helpers/mathHelper';

import styles from '../styles.module.less';

interface IHikingPrintFoodProps extends React.HTMLAttributes<HTMLDivElement> {
  dayData: IDayData;
  hikingFood: IHikingMenuFood[];
  hikingData: IHikingData;
  products: IHikingMenuExtendedProduct[];
}

const HikingPrintFood = ({
  dayData,
  hikingFood,
  hikingData,
  className,
  products,
  ...rest
}: IHikingPrintFoodProps) => {
  return (
    <A4SubPage {...rest} className={clsx(className)}>
      {dayData.schedules.some((sh) => sh.foodAct?.id) && (
        <div>
          <h3 className="mt-3">Приемы пищи</h3>
          <table
            className={clsx('table table-sm table-condensed table-bordered')}
            style={{ breakInside: 'avoid' }}
          >
            <tbody>
              {dayData.schedules
                .filter((sh) => sh.foodAct?.id)
                .map((sh) => {
                  const food = hikingFood?.filter(
                    (fa) =>
                      fa.date.toLocaleDateString() === sh.start.toLocaleDateString() &&
                      fa.id_act === sh.foodAct?.id,
                  );
                  if (!food?.length || !sh.foodAct) {
                    return null;
                  }

                  const hikersForAct = hikingData.hikers.filter((h) => {
                    let byStartDate = true;
                    let byFinishDate = true;
                    if (h.dateFrom) {
                      byStartDate = h.dateFrom <= sh.start;
                    }

                    if (h.dateTo) {
                      byFinishDate = h.dateTo >= sh.start;
                    }

                    return byStartDate && byFinishDate;
                  });

                  return food.map((f, foodIndex) => {
                    const assignee = f.assigneeUser;
                    return f.products.map((p, pi, pArr) => {
                      if (!sh.foodAct) return null;
                      const product = products.find((pr) => pr.id === p.id);
                      if (!product) return null;

                      return (
                        <tr key={`${f.id}-${sh.foodAct?.id}-${product.id}`}>
                          {pi === 0 && foodIndex === 0 && (
                            <td
                              rowSpan={hikingFood?.reduce(
                                (a, f1) =>
                                  f1.date.toLocaleDateString() === sh.start.toLocaleDateString() &&
                                  sh.foodAct?.id === f1.id_act
                                    ? a + f1.products.length
                                    : a,
                                0,
                              )}
                            >
                              <div className={styles.verticalText}>
                                <strong>{sh.foodAct.name}</strong>
                                <small className="d-block">
                                  &nbsp;
                                  <small>
                                    {sh.foodAct.kkalCurrent || sh.foodAct.kkalTarget}ккал
                                  </small>
                                  &nbsp;
                                  <small>
                                    {formattedLocaleTime(sh.start)} -{' '}
                                    {formattedLocaleTime(sh.finish)}
                                  </small>
                                </small>
                                {sh.is_self_sufficiency && (
                                  <>
                                    <br />
                                    <small className="text-danger">Самообеспечение</small>
                                  </>
                                )}
                              </div>
                            </td>
                          )}
                          {pi === 0 && (
                            <td rowSpan={pArr.length}>
                              <RecipeCookingInfo
                                className="float-end"
                                style={{ gap: 6 }}
                                members_count={hikersForAct.length}
                                cooking_time={f.cooking_time}
                                water_count={f.water_count}
                                gas_count={f.gas_count}
                              />
                              {f.name}
                              {f.text.length > 0 && (
                                <small
                                  className="d-block text-wrap text-info"
                                  dangerouslySetInnerHTML={{ __html: f.text }}
                                />
                              )}
                            </td>
                          )}

                          <td>
                            <small className="d-block text-nowrap text-truncate">
                              {product?.forcedUser && (
                                <small className="float-end">{product.forcedUser?.name}</small>
                              )}
                              {assignee && !product?.forcedUser && (
                                <small className="float-end">{assignee.name}</small>
                              )}
                              {p.name}
                            </small>
                          </td>
                          {/*<td className="text-end" style={{ width: 40 }}>*/}
                          {/*    <small>{p.amount}{hikersForAct.length !== hikingData?.hikers.length && <sup className="text-danger">&thinsp;×&thinsp;{hikersForAct.length}</sup>}</small>*/}
                          {/*</td>*/}
                          <td className="text-end" style={{ width: 40 }}>
                            <small>{round(p.amount * hikersForAct.length)}</small>
                          </td>
                        </tr>
                      );
                    });
                  });
                })}
            </tbody>
          </table>
        </div>
      )}
    </A4SubPage>
  );
};

export default HikingPrintFood;
