import React from 'react';

import A4Page from '@components/A4Page';

import { getHikingRepairKitItems } from '../../@services/hikingRepairKit.service';
import { HikingPosition } from '../../@types/hiking.rules';
import { IHikingData } from '../../@types/hiking.types';
import { IHikingRepairKit } from '../../@types/hikingRepairKit.types';
import HikingApproves from '../../approves/HikingApproves';

const HikingPrintRepairKit: React.FC<{ hikingData: IHikingData }> = ({ hikingData }) => {
  const [repairKitItems, setRepairKitItems] = React.useState<IHikingRepairKit[]>([]);

  React.useEffect(() => {
    getHikingRepairKitItems(hikingData.id).then(setRepairKitItems);
  }, [hikingData]);

  if (!repairKitItems.length) return null;

  const remMaster = hikingData.hikers.find((h) =>
    h.positions.find((p) => [HikingPosition.Remmaster].includes(p.id as HikingPosition)),
  );

  return (
    <A4Page>
      <h2>Состав ремонтного набора</h2>
      {remMaster && (
        <div className="text-end">
          Отв. реммастер:{' '}
          <em>
            {remMaster.name} {remMaster.surname}
          </em>
        </div>
      )}
      <table className="table table-sm table-condensed table-bordered">
        <thead>
          <tr>
            <th>
              <small>Наименование</small>
            </th>
            <th>
              <small>Вес</small>
            </th>
            <th>
              <small>Ответственный</small>
            </th>
            <th>
              <small>Комментарий</small>
            </th>
          </tr>
        </thead>
        <tbody>
          {repairKitItems.map((item) => {
            return (
              <tr key={item.id}>
                <td>
                  <small>{item.name}</small>
                </td>
                <td className="tex-right">
                  <small>{item.weight}</small>
                </td>
                <td>
                  <small>
                    {item.assignee
                      ? [item.assignee.name, item.assignee.surname].join(' ')
                      : 'реммастер'}
                  </small>
                </td>
                <td>
                  <small>{item.comment}</small>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
      <HikingApproves readonly entity_type="repair_kit" hikingData={hikingData} />
    </A4Page>
  );
};

export default HikingPrintRepairKit;
