import React from 'react';

import { HikingContext } from '@apps/Hiking/@contexts/hikingContext';
import PohodnikChevron from '@apps/Print/components/PohodnikChevron';
import A4Page from '@components/A4Page';

import logo2 from '../../../../img/logo/logo_2.png';

const HikingPrintFrontPage = () => {
  const hikingData = React.useContext(HikingContext);
  if (!hikingData) return 'has no hiking data';

  return (
    <A4Page>
      <img src={logo2} style={{ height: '1.5cm' }} />
      <div className="text-center" style={{ marginBottom: '3cm', marginTop: '7cm' }}>
        <h3>{hikingData.name}</h3>
        <p>
          {hikingData.type.name} поход. {hikingData.start.toLocaleDateString()} —{' '}
          {hikingData.finish.toLocaleDateString()}
        </p>
        <p>{hikingData.desc}</p>
      </div>
      <div className="text-center" style={{ marginTop: '2cm' }}>
        <PohodnikChevron
          style={{ width: 256, marginBottom: '1cm' }}
          subheader={
            hikingData.slogan || ['Походники Пензы', hikingData.finish.getFullYear()].join(' • ')
          }
          header={hikingData.name}
          url={hikingData.visual.photo}
        />

        <p>
          {hikingData.region.name}
          <br />
          {hikingData.finish.getFullYear()}
        </p>
      </div>
    </A4Page>
  );
};

export default HikingPrintFrontPage;
