import React from 'react';

import PatchCheck from '@pohodnik/icons/svg/Badges/PatchCheck';

import A4Page from '@components/A4Page';

import {
  IFirstAidKitApprove,
  IFirstAidKitSMedicament,
} from '../../../Medicaments/@types/firstAidKit.types';
import {
  getFirstAidKidApproversForHikingAsync,
  getFirstAidKidForHikingAsync,
} from '../../../Medicaments/services/firstAidKit.services';
import { HikingPosition } from '../../@types/hiking.rules';
import { IHikingData } from '../../@types/hiking.types';

const HikingPrintFirstAidKit: React.FC<{ hikingData: IHikingData }> = ({ hikingData }) => {
  const [data, setData] = React.useState<IFirstAidKitSMedicament[]>([]);
  const [approves, setApproves] = React.useState<IFirstAidKitApprove[]>([]);

  React.useEffect(() => {
    getFirstAidKidForHikingAsync(hikingData.id).then(setData);
    getFirstAidKidApproversForHikingAsync(hikingData.id).then(setApproves);
  }, [hikingData]);

  if (!data.length) return null;

  const medic = hikingData.hikers.find((h) =>
    h.positions.find((p) => [HikingPosition.Medic].includes(p.id as HikingPosition)),
  );

  const groupsMappedData: Record<string, IFirstAidKitSMedicament[]> = {};

  data.forEach((m) => {
    const k = m.medicament.category?.name || 'Без категории';
    if (!groupsMappedData[k]) {
      groupsMappedData[k] = [];
    }
    groupsMappedData[k].push(m);
  });

  return (
    <A4Page>
      <h2>Медицинская аптечка</h2>
      {medic && (
        <div className="text-end">
          Отв. медик:{' '}
          <em>
            {medic.name} {medic.surname}
          </em>
        </div>
      )}
      <table className="table table-sm table-condensed table-bordered">
        <thead>
          <tr>
            <th>Название</th>
            <th>Кол‑во</th>
            <th>Ед.</th>
            {/* <th>Дозировка</th>
          <th>Применение</th>
          <th>Противопоказания</th> */}
          </tr>
        </thead>
        <tbody>
          {Object.entries(groupsMappedData).map(([groupName, list]) => {
            return (
              <>
                {list.map((m, i) => (
                  <>
                    {i === 0 && (
                      <tr>
                        <td colSpan={3}>
                          <strong>{groupName}</strong>
                        </td>
                      </tr>
                    )}
                    <tr key={m.id}>
                      <td>
                        <small>- &nbsp;&nbsp;{m.medicament.name}</small>&nbsp;
                        {m.comment.length > 0 && (
                          <small>
                            <em className="text-muted">
                              <small>({m.comment})</small>
                            </em>
                          </small>
                        )}
                        {m.assignee && (
                          <small>
                            <em className="text-muted d-block">
                              <small>
                                ({['отв.', m.assignee.name, m.assignee.surname].join(' ')})
                              </small>
                            </em>
                          </small>
                        )}
                        {m.count_for_each > 0 && (
                          <small>
                            <em className="text-danger d-block">
                              <small>
                                По {m.count_for_each}
                                <small>
                                  {m.medicament.form?.name.substr(0, 3).toLocaleLowerCase()}
                                </small>{' '}
                                у каждого
                              </small>
                            </em>
                          </small>
                        )}
                      </td>
                      <td className="text-end">
                        <small>{m.amount}</small>
                      </td>
                      <td>
                        <small className="text-lower">
                          {m.medicament.form?.name.substr(0, 3).toLocaleLowerCase()}
                        </small>
                      </td>
                      {/* <td><small>{m.medicament.dosage}</small></td>
                <td><small>{m.medicament.usages}</small></td>
                <td><small>{m.medicament.contraindications}</small></td> */}
                    </tr>
                  </>
                ))}
              </>
            );
          })}
        </tbody>
      </table>
      {approves.map((approve) => {
        return (
          <div key={approve.id} className="d-flex align-items-center">
            <PatchCheck className="me-2" /> Утверждено: {approve.date.toLocaleString()} /{' '}
            {approve.position.name} / {approve.user.name}
          </div>
        );
      })}
    </A4Page>
  );
};

export default HikingPrintFirstAidKit;
