import React from 'react';

import { HikingContext } from '@apps/Hiking/@contexts/hikingContext';
import { IHikingEquip } from '@apps/Hiking/@types/equip.types';
import A4Page from '@components/A4Page';
import { digitsDivision } from '@helpers/formatHelper';

interface IHikingPrintCommonEquipPageProps {
  equip: IHikingEquip[];
}

const HikingPrintCommonEquipPage = ({ equip: hikingEquip }: IHikingPrintCommonEquipPageProps) => {
  const hikingData = React.useContext(HikingContext);
  if (!hikingData) return 'has no hiking data';

  return (
    <A4Page>
      <h2>Общее снаряжение</h2>
      <table className="table table-sm table-condensed table-bordered">
        <thead>
          <tr>
            <th>
              <small> Участник</small>
            </th>
            <th>
              <small>Элемент снаряжения</small>
            </th>
            <th>
              <small>Вес, г</small>
            </th>
          </tr>
        </thead>
        <tbody>
          {Object.entries(
            hikingEquip.reduce<Record<string, IHikingEquip[]>>((acc, val) => {
              const k = (val.user?.id ?? 0).toString();
              if (!acc[k]) {
                acc[k] = [];
              }

              acc[k].push(val);

              return acc;
            }, {}),
          ).map(([k, userItems]) => {
            return (
              <>
                {userItems
                  .filter((i) => i.isConfirm)
                  .map((item, i, arr) => {
                    return (
                      <tr key={`${k}-${item.id}`}>
                        {i == 0 && (
                          <th rowSpan={arr.length}>
                            <small>{item.user?.name}</small>
                          </th>
                        )}
                        <td>
                          <small>{item.name}</small>
                        </td>
                        <td className="text-end">
                          <small>{item.weight}</small>
                        </td>
                      </tr>
                    );
                  })}
                <tr>
                  <th colSpan={2} className="text-end">
                    <small>
                      {' '}
                      Итого <em>{userItems?.[0]?.user?.name}</em>:
                    </small>
                  </th>
                  <th className="text-end">
                    <small>
                      {' '}
                      {digitsDivision(
                        userItems.filter((i) => i.isConfirm).reduce((a, v) => a + v.weight, 0),
                      )}
                    </small>
                  </th>
                </tr>
              </>
            );
          })}
        </tbody>
        <tfoot>
          <tr>
            <th colSpan={2} className="text-end">
              <small>Итого на всех:</small>
            </th>
            <th className="text-end">
              <small>
                {' '}
                {digitsDivision(
                  hikingEquip.filter((i) => i.isConfirm).reduce((a, v) => a + v.weight, 0),
                )}
              </small>
            </th>
          </tr>
        </tfoot>
      </table>
    </A4Page>
  );
};

export default HikingPrintCommonEquipPage;
